            // ─── SLA CONFIGURATION & REALTIME TRACKING ENGINE ───────────
            DEFAULT_SLA_CONFIG: {
                step1: { stepNumber: 1, key: 'step1', name: 'Step 1: ศูนย์รับ Order, Design & BOQ', slaHours: 24, warningThresholdPct: 75, enabled: true, color: 'indigo' },
                step2: { stepNumber: 2, key: 'step2', name: 'Step 2: บันทึก Ticket & แปลง Project', slaHours: 12, warningThresholdPct: 75, enabled: true, color: 'emerald' },
                step3: { stepNumber: 3, key: 'step3', name: 'Step 3: เตรียมแผนงานและทีมช่าง', slaHours: 12, warningThresholdPct: 75, enabled: true, color: 'amber' },
                step4: { stepNumber: 4, key: 'step4', name: 'Step 4: แผนงาน & บันทึกช่าง', slaHours: 48, warningThresholdPct: 75, enabled: true, color: 'cyan' },
                step5: { stepNumber: 5, key: 'step5', name: 'Step 5: ตรวจรับรองคุณภาพ (QC)', slaHours: 24, warningThresholdPct: 75, enabled: true, color: 'teal' },
                step6: { stepNumber: 6, key: 'step6', name: 'Step 6: ประเมินความพึงพอใจ (CSAT)', slaHours: 24, warningThresholdPct: 75, enabled: true, color: 'blue' }
            },

            getSLAConfig() {
                try {
                    const saved = localStorage.getItem('pmt_sla_config');
                    if (saved) {
                        const parsed = JSON.parse(saved);
                        return Object.assign({}, this.DEFAULT_SLA_CONFIG, parsed);
                    }
                } catch(e) {}
                return JSON.parse(JSON.stringify(this.DEFAULT_SLA_CONFIG));
            },

            saveSLAConfig(config) {
                try {
                    localStorage.setItem('pmt_sla_config', JSON.stringify(config));
                } catch(e) {}
                this.updateAllStepDashboards();
            },
            // Universal Job Finder: รองรับ id เป็น number, string, job_no, หรือ external_ref_id
            getJob(id) {
                if (id === null || id === undefined) return null;
                const strId = String(id).trim();
                return (DB.jobs || []).find(j => 
                    j.id === id || 
                    String(j.id) === strId || 
                    j.job_no === strId || 
                    j.id == id || 
                    (j.job_no && String(j.job_no).toLowerCase() === strId.toLowerCase()) ||
                    (j.external_ref_id && String(j.external_ref_id) === strId)
                ) || null;
            },

            isQuickJob(job) {
                if (!job) return false;
                const jt = (job.job_type || '').toLowerCase().trim();
                if (jt === 'quick') return true;
                if (jt === 'renovate' || jt === 'ma') return false;
                const s = (job.service || '').toLowerCase();
                if (s.includes('renovate') || s.includes('กระเบื้อง') || s.includes('ทาสี') || s.includes('ฉากกั้น') || s.includes('ครัว')) {
                    return false;
                }
                if (s.includes('ma') || s.includes('สัญญา') || s.includes('ล้าง') || s.includes('บำรุง') || s.includes('รอบ')) {
                    return false;
                }
                return true;
            },

            isDesignFinalV2(job) {
                if (!job) return false;
                if (this.isQuickJob(job)) return true; // Quick Services bypass Design & BOQ
                const jobId = job.id || job.job_no;
                const bps = (DB.blueprints || []).filter(b => b.jobId === jobId || String(b.jobId) === String(jobId));
                if (!bps || bps.length === 0) return false;
                return bps.some(b => {
                    const v = String(b.version || '').toLowerCase().trim();
                    return v.includes('v2.0') || v.includes('v2 final') || v.includes('v2 approved') || (v.includes('v2') && v.includes('final')) || v.includes('สมบูรณ์');
                });
            },

            calculateJobSLA(job, stepNumber) {
                if (!job) return null;
                const config = this.getSLAConfig();
                const stepKey = `step${stepNumber}`;
                const stepCfg = config[stepKey] || this.DEFAULT_SLA_CONFIG[stepKey];
                if (!stepCfg || !stepCfg.enabled) return null;

                const ts = job.step_timestamps || {};
                let startIso = null;

                if (stepNumber === 1) {
                    startIso = ts.step1_intake_at || ts.step1_order_at || job.created_at || (job.date ? `${job.date}T08:30:00.000Z` : null);
                } else if (stepNumber === 2) {
                    startIso = ts.step2_ticket_at || ts.step4_ticket_at || ts.step1_accepted_at || ts.step1_order_at || job.created_at;
                } else if (stepNumber === 3) {
                    startIso = ts.step3_conversion_at || ts.step5_project_at || ts.step2_ticket_at || ts.step4_ticket_at;
                } else if (stepNumber === 4) {
                    startIso = ts.step4_gantt_at || ts.step3_conversion_at || ts.step5_project_at;
                } else if (stepNumber === 5) {
                    startIso = ts.qc_pending_at || ts.step4_gantt_at || ts.step3_conversion_at;
                } else if (stepNumber === 6) {
                    startIso = ts.csat_pending_at || ts.qc_passed_at || ts.qc_inspected_at;
                }

                if (!startIso) return null;

                const startDate = new Date(startIso);
                if (isNaN(startDate.getTime())) return null;

                const now = new Date();
                const elapsedMs = Math.max(0, now.getTime() - startDate.getTime());
                const elapsedHours = elapsedMs / (1000 * 60 * 60);
                const slaTargetHours = Number(stepCfg.slaHours || 24);
                const warningHours = slaTargetHours * (Number(stepCfg.warningThresholdPct || 75) / 100);

                let status = 'ON_TIME'; // ON_TIME | WARNING | OVERDUE
                if (elapsedHours > slaTargetHours) {
                    status = 'OVERDUE';
                } else if (elapsedHours >= warningHours) {
                    status = 'WARNING';
                }

                const diffHours = Math.abs(slaTargetHours - elapsedHours);
                const remainingHrs = Math.floor(diffHours);
                const remainingMins = Math.floor((diffHours - remainingHrs) * 60);
                const timeString = remainingHrs > 0 ? `${remainingHrs} ชม. ${remainingMins} น.` : `${remainingMins} นาที`;

                let badgeHtml = '';
                if (status === 'OVERDUE') {
                    badgeHtml = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-mono font-bold bg-rose-500/15 text-rose-600 dark:text-rose-400 border border-rose-500/30" title="เกินกำหนด SLA แล้ว +${timeString}"><span class="w-1.5 h-1.5 rounded-full bg-rose-500 animate-ping"></span>เกิน SLA +${timeString}</span>`;
                } else if (status === 'WARNING') {
                    badgeHtml = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-mono font-bold bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/30" title="ใกล้ครบกำหนด SLA เหลือเวลา ${timeString}"><span class="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse"></span>ใกล้ครบ SLA (${timeString})</span>`;
                } else {
                    badgeHtml = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-mono font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20" title="อยู่ในเกณฑ์ SLA เป้าหมาย ${slaTargetHours} ชม."><i class="ph ph-check-circle text-xs"></i>ในเกณฑ์ (เหลือ ${timeString})</span>`;
                }

                return {
                    status,
                    elapsedHours,
                    slaTargetHours,
                    diffHours,
                    timeString,
                    badgeHtml
                };
            },

