                const step2Date = tkt ? (tkt.created_at || '2026-09-04T10:15:40.000Z') : (ts.step2_ticket_at || ts.step4_ticket_at || (step2Done ? '2026-09-04T10:15:40.000Z' : null));

                // Step 3: Work Preparation & Dispatch
