            switchFaqTab(tabKey) {
                this.state.currentFaqTab = tabKey;
                const tabs = ['training', 'pipeline', 'faq'];
                tabs.forEach(t => {
                    const btn = document.getElementById(`faq-tab-${t}`);
                    const content = document.getElementById(`faq-content-${t}`);
                    if (btn) {
                        if (t === tabKey) {
                            btn.className = 'px-4 py-2 text-xs font-semibold rounded-xl bg-brand-500 text-white shadow-xs flex items-center gap-1.5 transition-all cursor-pointer';
                        } else {
                            btn.className = 'px-4 py-2 text-xs font-medium rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted/50 flex items-center gap-1.5 transition-all cursor-pointer';
                        }
                    }
                    if (content) {
                        if (t === tabKey) {
                            content.classList.remove('hidden');
                        } else {
                            content.classList.add('hidden');
                        }
                    }
                });
            },

            showToast(msg) {
                const t = document.getElementById('toast');
                document.getElementById('toast-msg').innerHTML = msg;
                t.classList.remove('translate-y-20', 'opacity-0');
                setTimeout(() => {
                    t.classList.add('translate-y-20', 'opacity-0');
                }, 3200);
            },

            showModal(id) {
                const m = document.getElementById(id);
                if (!m) return;
                if (id === 'modal-create-job') {
                    this.initCreateJobModal();
                }
                m.classList.remove('hidden-view');
                setTimeout(() => {
                    m.classList.remove('opacity-0');
                    const dialog = m.querySelector('#' + id + '-content') || m.querySelector('div');
                    if (dialog) dialog.classList.remove('scale-95');
                }, 10);
            },

            hideModal(id) {
                const m = document.getElementById(id);
                if (!m) return;
                m.classList.add('opacity-0');
                const dialog = m.querySelector('#' + id + '-content') || m.querySelector('div');
                if(dialog) dialog.classList.add('scale-95');
                setTimeout(() => {
                    m.classList.add('hidden-view');
                }, 200);
            },

            handleGlobalSearch(e) {
                const query = e.target.value.toLowerCase().trim();
                if(e.key === 'Enter' && query) {
                    this.navigate('jobs');
                    const filtered = DB.jobs.filter(j => 
                        j.id.toLowerCase().includes(query) || 
                        j.customer.toLowerCase().includes(query) || 
                        j.phone.includes(query) ||
                        j.service.toLowerCase().includes(query)
                    );
                    this.renderJobs(filtered);
                }
            },

