                const slaCfg2 = (this.getSLAConfig()).step2 || this.DEFAULT_SLA_CONFIG.step2;
                const elTarget = document.getElementById('step2-sla-target-label');
                if (elTarget) elTarget.innerText = `${slaCfg2.slaHours} ชม.`;

                // Distribution
